import{_ as a,D as s,c as i,I as o,a4 as e,o as r}from"./chunks/framework.CRCV4hx_.js";const v=JSON.parse('{"title":"Availability Search Overview","description":"","frontmatter":{},"headers":[],"relativePath":"availability-search-component.md","filePath":"availability-search-component.md"}'),n={name:"availability-search-component.md"},d=e('<h1 id="availability-search-overview" tabindex="-1">Availability Search Overview <a class="header-anchor" href="#availability-search-overview" aria-label="Permalink to &quot;Availability Search Overview&quot;">​</a></h1><p>The AvailabilitySearch Livewire component is the main component that you&#39;ll use to add the reservation functionality to your site. It allows the user to search for a date or date range, by specific <a href="./rates">rate</a> and select the quantity that they want to book.</p><p>In this page, we&#39;ll go over the basics of how to use the component, and then we&#39;ll explain how to use it to search for availability of a <a href="./availability-search-single">single entry</a> or how to pair it with <a href="https://livewirefilters.com/" target="_blank" rel="noreferrer">Livewire Filters</a> or Statamic&#39;s Collection Tag in order to search for all <a href="./availability-search-multiple">available entries</a> for a specific date or dates.</p><h2 id="component-basics" tabindex="-1">Component basics <a class="header-anchor" href="#component-basics" aria-label="Permalink to &quot;Component basics&quot;">​</a></h2><p>In its most simple form, you can include the AvailabilitySearch component in your Antlers templates like so:</p><div class="language-antlers vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">antlers</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">livewire</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">availability</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">search</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> calendar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;range&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><p>More often than not, you&#39;ll also want to include the <a href="./availability-results">AvailabilityResults</a> component to display the results of the search and the &quot;Book now&quot; button that starts the checkout process.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Each search that the user makes is saved in the session (under the key <code>resrv-search</code>), so that their search persists between page loads.</p></div>',8),l=e(`<h2 id="component-properties" tabindex="-1">Component properties <a class="header-anchor" href="#component-properties" aria-label="Permalink to &quot;Component properties&quot;">​</a></h2><p>Of course, there are quite a few properties that you can set depending on the use case. Here&#39;s a list of all the available properties:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>calendar</td><td>string</td><td>&quot;single&quot;</td><td>The calendar type to use. <code>single</code> selects a single date, <code>range</code> selects a date range.</td></tr><tr><td>live</td><td>boolean</td><td>true</td><td>When enabled, the component automatically updates the results when the user changes any value of their search. When disabled, the component only updates when the user clicks the &quot;Search&quot; button.</td></tr><tr><td>rates</td><td>boolean</td><td>false</td><td>When enabled, the <a href="./rates">rate</a> selector is rendered so the user can pick a rate. Pass <code>:rates=&quot;true&quot;</code>. (Replaces the v5 <code>advanced</code> property: it&#39;s now a plain boolean.)</td></tr><tr><td>anyRate</td><td>boolean</td><td>false</td><td><strong>Usable when searching for multiple entries.</strong> When enabled, an unselected rate is sent as &quot;any&quot; and the results return the cheapest rate that is available. Search is also allowed without dates. Pass <code>:any-rate=&quot;true&quot;</code>.</td></tr><tr><td>enableQuantity</td><td>boolean</td><td>false</td><td>When enabled, a quantity control is added so that the user can book more than one product at once.</td></tr><tr><td>redirectTo</td><td>string</td><td>null</td><td>If live mode is disabled, the page to redirect to when the user clicks &quot;Search&quot;.</td></tr><tr><td>resetOnBoot</td><td>boolean</td><td>false</td><td>When enabled, on mount the component resets the quantity to <code>1</code> and the rate to <code>null</code>, ignoring whatever is saved in the session. Useful to discard a stale search on a landing page.</td></tr><tr><td>overrideRates</td><td>array</td><td>[]</td><td>A <code>rate_id =&gt; label</code> map that overrides the rates resolved from the database for this entry/collection.</td></tr><tr><td>showAvailabilityOnCalendar</td><td>boolean</td><td>false</td><td>Show availability &amp; pricing information on the calendar. Usable only when browsing <a href="./availability-search-single#display-availability-in-the-calendar">a specific entry</a>.</td></tr><tr><td>entry</td><td>string</td><td>null</td><td><strong>Needs to be a Statamic Entry ID.</strong> Used to resolve the per-entry rate labels and required when <em>showAvailabilityOnCalendar</em> is enabled. Optional for collection-wide search.</td></tr><tr><td>ratesBlueprint</td><td>string</td><td>null</td><td>Optional. Carries the <code>collection.blueprint</code> reference when needed (mainly for the Livewire Filters path). Not required for normal single/collection search, since rates are now collection-scoped database records.</td></tr><tr><td>view</td><td>string</td><td>&quot;availability-search&quot;</td><td>Override the view that&#39;s used to render the component. Really useful when you want different versions of the AvailabilitySearch component on different pages. Expects a <code>name.blade.php</code> file in the <code>/resources/views/vendor/statamic-resrv/livewire</code> folder.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">UPGRADING FROM v5</p><p>Several properties were renamed in v6 as part of the move to the <a href="./rates">Rates</a> system: <code>advanced</code> → <code>rates</code>, <code>anyAdvanced</code> → <code>anyRate</code>, <code>overrideProperties</code> → <code>overrideRates</code>. The boot-reset property is <code>resetOnBoot</code> (the v5 docs mistakenly called it <code>resetAdvancedOnBoot</code>). See <a href="./upgrading">Upgrading to v6</a> for the full list.</p></div><h2 id="customizing" tabindex="-1">Customizing <a class="header-anchor" href="#customizing" aria-label="Permalink to &quot;Customizing&quot;">​</a></h2><p>The design of the Availability Search component is very basic by default, since it&#39;s meant to be modified to fit your layout. To modify it, make sure you&#39;ve published the views during checkout and edit the <code>/resources/views/vendor/statamic-resrv/livewire/availability-search.blade.php</code> file.</p><p>In the same path, inside the <code>components</code> folder, you can find and customize the Blade components that are used by the Availability Search component. The rate selector lives in <code>components/availability-rates.blade.php</code>.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>The component can be used in three different ways:</p><ol><li><strong>As a standalone search form that redirects to a results page.</strong> This is something that you&#39;d probably use on the homepage of a site. To use it this way, you can set <code>live</code> to false and <code>redirectTo</code> to the Entry ID of the page you want to redirect to.</li><li><strong>As a search form inside a single Entry.</strong> When you want your user to search for a single Entry, usually on the aforementioned Entry&#39;s page. Follow along at <a href="./availability-search-single">single entry</a> for examples.</li><li><strong>As a search form on an index page.</strong> When you want the user to input their search and list all available Entries. You can find your options on the <a href="./availability-search-multiple">multiple entries</a> page.</li></ol><h2 id="passing-data-to-checkout" tabindex="-1">Passing data to checkout <a class="header-anchor" href="#passing-data-to-checkout" aria-label="Permalink to &quot;Passing data to checkout&quot;">​</a></h2><p>There are some cases where you might want to pass some data to the checkout page before the user gets there. A good example is the <a href="./guests">Guests component</a> where we pass along the number of guests to the checkout page. To achieve that you can bind the control you want to use to the <code>data.customer.handle</code> property of the <code>AvailabilitySearch</code> component. Just make sure to create the appropriate fields in your <a href="./checkout#checkout-form">checkout form</a>. If you don&#39;t want to allow the user to edit them, remember to set them as <code>hidden</code> fields in your blueprint.</p><h2 id="disabling-dates-of-the-week" tabindex="-1">Disabling dates of the week <a class="header-anchor" href="#disabling-dates-of-the-week" aria-label="Permalink to &quot;Disabling dates of the week&quot;">​</a></h2><p>In some cases you might want to disable specific days of the week. To do so, you need to edit your <code>availability-search.blade.php</code> file (make sure you <a href="./installation">publish your views during installation</a> or by running <code>php artisan vendor:publish --tag=resrv-checkout-views</code>) and add a <code>disabledDays</code> array to the <code>x-resrv::availability-dates</code> component like so:</p><div class="language-blade vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">blade</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">x-resrv::availability-dates</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    :$calendar</span></span>
<span class="line highlighted"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    disabledDays</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[&quot;Saturday&quot;, &quot;Sunday&quot;]&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    :errors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$errors&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div><p>The array uses full English day names (<code>Sunday</code>, <code>Monday</code>, <code>Tuesday</code>, <code>Wednesday</code>, <code>Thursday</code>, <code>Friday</code>, <code>Saturday</code>).</p>`,16);function h(c,p,u,y,b,g){const t=s("Image");return r(),i("div",null,[d,o(t,{src:"./img/resrv-availability-search.webp",alt:"A very simple AvailabilitySearch component with its pal, AvailabilityResults"}),l])}const k=a(n,[["render",h]]);export{v as __pageData,k as default};
